    {
        _playbackTimer = new DispatcherTimer
        {
            Interval = TimeSpan.FromSeconds(1)
        };
        _playbackTimer.Tick += OnPlaybackTimerTick;

        // 初始化播放時間字串與音量狀態標籤
        UpdatePlaybackTimeDisplay();
        UpdateVolumeState(VolumeValue);
    }

    // =========================================================================
    // 可觀察屬性 (Observable Properties)
