    // =========================================================================
    // 屬性變更攔截與響應 (Property Change Handlers)
    // =========================================================================

    partial void OnPositionValueChanged(double value)
    {
        // 避免計時器更新 PositionValue 時觸發遞迴 Seek
        if (_isUpdatingPositionFromTimer) return;

        _currentSeconds = Math.Clamp((value / 100.0) * TotalSeconds, 0, TotalSeconds);
        UpdatePlaybackTimeDisplay();
        SeekRequested?.Invoke(TimeSpan.FromSeconds(_currentSeconds));
    }

    partial void OnVolumeValueChanged(double value)
    {
        UpdateVolumeState(value);
        VolumeChangedRequested?.Invoke(value);
    }

    private void UpdateVolumeState(double value)
    {
        if (value <= 0.001)
        {
            IsMuted = true;
            VolumeLabel = "音量 (靜音)：";
        }
        else
        {
            IsMuted = false;
            _previousVolume = value;
            VolumeLabel = $"音量 ({Math.Round(value)}%)：";
        }
    }

    // =========================================================================
    // 播放模擬計時器迴圈 (Playback Simulation Timer Loop)
    // =========================================================================

    private void OnPlaybackTimerTick(object? sender, EventArgs e)
    {
        if (!IsPlaying) return;

        _currentSeconds += 1.0;

        if (_currentSeconds >= TotalSeconds)
        {
            if (IsLooping)
            {
                _currentSeconds = 0;
            }
            else
            {
                _currentSeconds = TotalSeconds;
                StopInternal();
                return;
            }
        }

        UpdatePlaybackTimeDisplay();

        _isUpdatingPositionFromTimer = true;
        PositionValue = Math.Round((_currentSeconds / TotalSeconds) * 100.0, 1);
        _isUpdatingPositionFromTimer = false;
    }

    private void UpdatePlaybackTimeDisplay()
    {
        var currentTs = TimeSpan.FromSeconds(_currentSeconds);
        var totalTs = TimeSpan.FromSeconds(TotalSeconds);

        CurrentTimeText = $"{(int)currentTs.TotalMinutes:D2}:{currentTs.Seconds:D2}";
        TotalTimeText = $"{(int)totalTs.TotalMinutes:D2}:{totalTs.Seconds:D2}";
        TimeDisplay = $"{CurrentTimeText} / {TotalTimeText}";
    }

    private void StopInternal()
    {
        IsPlaying = false;
        _playbackTimer.Stop();
        PlayStatusText = "播放器狀態：已停止 (Stopped) | 格式：AAC / 48kHz Stereo | 輸出：立體聲聲道 | 緩衝：100%";
        StopRequested?.Invoke();
    }

