    [RelayCommand]
    private async Task PauseAsync()
    {
        IsPlaying = false;
        _playbackTimer.Stop();
        PlayStatusText = "播放器狀態：已暫停 (Paused) | 格式：AAC / 48kHz Stereo | 輸出：立體聲聲道 | 緩衝：100%";
        PauseRequested?.Invoke();
        await Task.CompletedTask;
    }

    /// <summary>
    /// 停止播放並重設播放時間至 00:00。
    /// </summary>
    [RelayCommand]
    private async Task StopAsync()
    {
        IsPlaying = false;
        _playbackTimer.Stop();
        _currentSeconds = 0;
        UpdatePlaybackTimeDisplay();

        _isUpdatingPositionFromTimer = true;
        PositionValue = 0;
        _isUpdatingPositionFromTimer = false;

        PlayStatusText = "播放器狀態：已停止 (Stopped) | 格式：AAC / 48kHz Stereo | 輸出：立體聲聲道 | 緩衝：100%";
        StopRequested?.Invoke();
        await Task.CompletedTask;
    }

    /// <summary>
    /// 切換靜音狀態 (Mute / Unmute)。
    /// </summary>
    [RelayCommand]
    private async Task ToggleMuteAsync()
    {
        if (IsMuted)
        {
            VolumeValue = _previousVolume > 0 ? _previousVolume : 50;
        }
        else
        {
            _previousVolume = VolumeValue;
            VolumeValue = 0;
        }
        await Task.CompletedTask;
    }

    /// <summary>
    /// 靜音命令別名。
    /// </summary>
    [RelayCommand]
    private async Task MuteAsync()
